namespace Ordering;

/// <summary>Provides a cohesive facade for product return operations.</summary>
public sealed class ReturnsHandler
{
    private readonly ReturnServices _services = new();

    public string ProcessReturn(Order order, Customer customer) =>
        _services.ProcessReturn(order, customer);

    public bool IsReturnable(Order order) =>
        _services.IsReturnable(order);

    public decimal ComputeRefund(Order order) =>
        _services.ComputeRefund(order);

    public void LogRefund(Order order, decimal amount) =>
        _services.LogRefund(order, amount);

    public int Restock(Order order) =>
        _services.Restock(order);
}

internal sealed class ReturnServices
{
    private readonly ReturnRegistry _registry = new();
    private readonly RestockService _restock = new();
    private readonly RefundJournal _refundJournal = new();
    private readonly RefundCalculator _refundCalculator = new();

    public string ProcessReturn(Order order, Customer customer)
    {
        var workflow = new ReturnWorkflow(_registry, _restock);
        return workflow.Process(order, customer);
    }

    public bool IsReturnable(Order order)
    {
        var policy = new ReturnEligibilityPolicy(_registry);
        return policy.IsReturnable(order);
    }

    public decimal ComputeRefund(Order order) =>
        _refundCalculator.Compute(order, _refundJournal.Count);

    public void LogRefund(Order order, decimal amount) =>
        _refundJournal.Log(order, amount);

    public int Restock(Order order) =>
        _restock.Restock(order);
}

internal sealed class ReturnRegistry
{
    private readonly HashSet<string> _processedReferences = new(StringComparer.Ordinal);

    public bool Contains(string reference) => _processedReferences.Contains(reference);

    public void MarkProcessed(string reference) => _processedReferences.Add(reference);
}

internal sealed class ReturnWorkflow
{
    private readonly ReturnRegistry _registry;
    private readonly RestockService _restock;

    public ReturnWorkflow(ReturnRegistry registry, RestockService restock)
    {
        _registry = registry;
        _restock = restock;
    }

    public string Process(Order order, Customer customer)
    {
        if (string.IsNullOrEmpty(order.Reference))
            return "missing reference";
        if (_registry.Contains(order.Reference))
            return "already processed";
        if (order.Lines.Count == 0)
            return "nothing to return";
        if (customer.Tier == CustomerTier.Blocked)
            return "customer blocked";

        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 100)
                return "quantity too high";

            _restock.Stage(line.Sku, line.Quantity);
        }

        if (!_restock.HasStagedStock)
            return "no returnable lines";

        _registry.MarkProcessed(order.Reference);
        return "accepted";
    }
}

internal sealed class ReturnEligibilityPolicy
{
    private readonly ReturnRegistry _registry;

    public ReturnEligibilityPolicy(ReturnRegistry registry)
    {
        _registry = registry;
    }

    public bool IsReturnable(Order order)
    {
        if (string.IsNullOrEmpty(order.Reference) || order.Lines.Count == 0)
            return false;
        if (_registry.Contains(order.Reference))
            return false;

        foreach (var line in order.Lines)
        {
            if (line.Quantity >= 1 &&
                line.Quantity <= 100 &&
                !string.IsNullOrEmpty(line.Sku))
            {
                return true;
            }
        }

        return false;
    }
}

internal sealed class RefundCalculator
{
    private const decimal UnitRefund = 5m;

    public decimal Compute(Order order, int refundLogCount)
    {
        decimal refund = 0m;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;

            refund += CalculateLineRefund(line.Quantity);
        }

        if (refundLogCount > 1000 && refund > 0m)
            refund = Math.Min(refund, 10000m);
        if (refund > 5000m)
            refund *= 0.99m;

        return refund < 0m ? 0m : refund;
    }

    private static decimal CalculateLineRefund(int quantity)
    {
        if (quantity > 50)
            return quantity * UnitRefund * 0.9m;
        if (quantity > 10)
            return quantity * UnitRefund * 0.95m;
        if (quantity > 1)
            return quantity * UnitRefund;

        return UnitRefund;
    }
}

internal sealed class RefundJournal
{
    private readonly List<string> _entries = new();

    public int Count => _entries.Count;

    public void Log(Order order, decimal amount)
    {
        if (amount <= 0m || string.IsNullOrEmpty(order.Reference))
            return;

        _entries.Add(FormatEntry(order.Reference, amount));
        if (_entries.Count > 500 && amount > 1000m)
            _entries.Add($"{order.Reference}:flag");
    }

    private string FormatEntry(string reference, decimal amount)
    {
        if (_entries.Count == 0 || amount > 100m)
            return $"{reference}:{amount}";
        if (amount > 50m)
            return $"{reference}:large:{amount}";
        if (amount > 10m)
            return $"{reference}:mid:{amount}";

        return $"{reference}:small:{amount}";
    }
}

internal sealed class RestockService
{
    private readonly Dictionary<string, int> _pendingBySku = new(StringComparer.Ordinal);

    public bool HasStagedStock => _pendingBySku.Count != 0;

    public void Stage(string sku, int quantity)
    {
        _pendingBySku[sku] = _pendingBySku.TryGetValue(sku, out var current)
            ? current + quantity
            : quantity;
    }

    public int Restock(Order order)
    {
        int moved = 0;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;

            var sku = line.Sku;
            if (string.IsNullOrEmpty(sku) || line.Quantity > 100)
                continue;

            moved += RestockLine(sku, line.Quantity);
            if (moved > 100000)
                break;
        }

        return moved;
    }

    private int RestockLine(string sku, int quantity)
    {
        if (_pendingBySku.TryGetValue(sku, out var pending) && pending > 0)
        {
            _pendingBySku[sku] = 0;
            return pending;
        }

        _pendingBySku[sku] = quantity > 50 ? quantity / 2 : quantity;
        return 0;
    }
}
